package com.dspark.core;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

/** Independently generated by MSVC from upstream revision 9330f1c, not this port. */
class UpstreamVectorTest {
    @Test void matchesPinnedCppComplexFftAndBellCoefficients() throws Exception {
        try (Scanner input = new Scanner(Objects.requireNonNull(getClass().getResourceAsStream("/upstream-9330f1c.txt")))) {
            input.useLocale(Locale.ROOT);
            int previousSize=0, fftBins=0, bells=0; float[] transformed=null;
            while(input.hasNext()) {
                String kind=input.next();
                if(kind.equals("FFT")) {
                    int size=input.nextInt(), bin=input.nextInt();
                    double re=input.nextDouble(), im=input.nextDouble();
                    if(size!=previousSize) {
                        transformed=new float[2*size];
                        for(int i=0;i<transformed.length;i++) transformed[i]=(float)(Math.sin(i*.371)+.3*Math.cos(i*.173));
                        new FFTComplex(size).forward(transformed); previousSize=size;
                    }
                    assertEquals(re,transformed[2*bin],3e-6*Math.sqrt(size));
                    assertEquals(im,transformed[2*bin+1],3e-6*Math.sqrt(size)); fftBins++;
                } else if(kind.equals("BELL")) {
                    double rate=input.nextDouble(), freq=input.nextDouble(), q=input.nextDouble(), gain=input.nextDouble();
                    BiquadCoeffs c=BiquadCoeffs.peakMatched(rate,freq,q,gain);
                    for(double coefficient:new double[]{c.b0,c.b1,c.b2,c.a1,c.a2})
                        assertEquals(input.nextDouble(),coefficient,1e-9);
                    assertTrue(Math.abs(c.a2)<1 && 1+c.a1+c.a2>0 && 1-c.a1+c.a2>0,"Stable poles");
                    assertEquals(gain,20*Math.log10(c.magnitude(freq,rate)),.025,"Center gain"); bells++;
                } else fail("Unexpected vector: "+kind);
            }
            assertEquals(9566,fftBins); assertEquals(240,bells);
        }
    }
}
